-- Keep events.price_min / price_max in sync with ticket types.
create or replace function public.sync_event_price()
returns trigger language plpgsql security definer set search_path = '' as $$
declare
  ev uuid := coalesce(new.event_id, old.event_id);
begin
  update public.events e
  set price_min = p.min_price, price_max = p.max_price
  from (
    select min(price) as min_price, max(price) as max_price
    from public.ticket_types where event_id = ev
  ) p
  where e.id = ev and e.registration_mode = 'tickets';
  return null;
end;
$$;

create trigger ticket_types_sync_price after insert or update or delete on public.ticket_types
  for each row execute function public.sync_event_price();

create trigger registrations_updated_at before update on public.registrations
  for each row execute function public.set_updated_at();

-- Public counts for event cards ("42 going", "3 spots left") without exposing who registered.
create or replace function public.event_counts(event_ids uuid[])
returns table (event_id uuid, going int, waitlisted int, pending int)
language sql stable security definer set search_path = '' as $$
  select
    r.event_id,
    count(*) filter (where r.status = 'going')::int,
    count(*) filter (where r.status = 'waitlisted')::int,
    count(*) filter (where r.status in ('pending', 'awaiting_payment'))::int
  from public.registrations r
  where r.event_id = any (event_ids)
  group by r.event_id;
$$;

-- Registration rules: tickets, approvals, waitlist, payments hand-off, check-in.
-- All writes to public.registrations go through these functions (RLS allows no direct writes).

-- Spots currently taken: going + awaiting approval + unpaid checkouts younger than 30 minutes.
create or replace function public.taken_spots(p_event_id uuid, p_ticket_type_id uuid default null, p_exclude_user uuid default null)
returns int language sql stable security definer set search_path = '' as $$
  select count(*)::int
  from public.registrations r
  where r.event_id = p_event_id
    and (p_ticket_type_id is null or r.ticket_type_id = p_ticket_type_id)
    and (p_exclude_user is null or r.user_id <> p_exclude_user)
    and (
      r.status in ('going', 'pending')
      or (r.status = 'awaiting_payment' and r.updated_at > now() - interval '30 minutes')
    );
$$;

-- Is there room for one more on this event (and this ticket type)?
create or replace function public.has_room(p_event_id uuid, p_ticket_type_id uuid, p_exclude_user uuid default null)
returns boolean language plpgsql stable security definer set search_path = '' as $$
declare
  cap int;
  qty int;
begin
  select capacity into cap from public.events where id = p_event_id;
  select quantity into qty from public.ticket_types where id = p_ticket_type_id;
  if cap is not null and public.taken_spots(p_event_id, null, p_exclude_user) >= cap then
    return false;
  end if;
  if qty is not null and public.taken_spots(p_event_id, p_ticket_type_id, p_exclude_user) >= qty then
    return false;
  end if;
  return true;
end;
$$;

-- ─── Register ───────────────────────────────────────────────────────────────
-- Free → going. Paid → awaiting_payment (app then opens checkout). Approval on → pending.
-- Full → waitlisted (if the waitlist is on). Re-registering after cancelling reuses the row.
create or replace function public.register_for_event(
  p_event_id uuid,
  p_ticket_type_id uuid default null,
  p_answers jsonb default '{}'::jsonb
)
returns public.registrations
language plpgsql security definer set search_path = '' as $$
declare
  uid uuid := auth.uid();
  ev public.events;
  tt public.ticket_types;
  existing public.registrations;
  q record;
  new_status text;
  result public.registrations;
begin
  if uid is null then
    raise exception 'Sign in to register';
  end if;

  select * into ev from public.events where id = p_event_id for update;
  if ev.id is null or ev.status <> 'published'
     or (ev.organiser_id is not null and not exists (
       select 1 from public.organisers o where o.id = ev.organiser_id and o.status = 'approved')) then
    raise exception 'This event is not open for registration';
  end if;
  if ev.registration_mode <> 'tickets' then
    raise exception 'This event takes registrations on the organiser''s own site';
  end if;
  if coalesce(ev.ends_at, ev.starts_at) < now() then
    raise exception 'This event has already ended';
  end if;
  if ev.registration_deadline is not null and ev.registration_deadline < now() then
    raise exception 'Registration has closed';
  end if;

  if p_ticket_type_id is null then
    select * into tt from public.ticket_types where event_id = ev.id order by sort_order, created_at limit 1;
  else
    select * into tt from public.ticket_types where id = p_ticket_type_id and event_id = ev.id;
  end if;
  if tt.id is null then
    raise exception 'Choose a valid ticket';
  end if;
  if tt.sales_end_at is not null and tt.sales_end_at < now() then
    raise exception 'Sales for this ticket have ended';
  end if;

  for q in select id, label from public.event_questions where event_id = ev.id and required loop
    if coalesce(trim(both from p_answers ->> q.id::text), '') in ('', '[]', 'false') then
      raise exception 'Please answer: %', q.label;
    end if;
  end loop;

  select * into existing from public.registrations where event_id = ev.id and user_id = uid;
  if existing.id is not null and existing.status not in ('cancelled') then
    if existing.status = 'declined' then
      raise exception 'The organiser didn''t accept your registration for this event';
    end if;
    return existing;  -- already registered: idempotent
  end if;

  if not public.has_room(ev.id, tt.id, uid) then
    if ev.waitlist_enabled then
      new_status := 'waitlisted';
    else
      raise exception 'This event is full';
    end if;
  elsif ev.requires_approval then
    new_status := 'pending';
  elsif tt.price > 0 then
    new_status := 'awaiting_payment';
  else
    new_status := 'going';
  end if;

  if existing.id is not null then
    update public.registrations set
      ticket_type_id = tt.id, status = new_status, answers = coalesce(p_answers, '{}'::jsonb),
      amount = tt.price, currency = tt.currency,
      payment_status = case when tt.price > 0 then 'pending' else 'none' end,
      stripe_checkout_session_id = null, checked_in_at = null, checked_in_by = null, decided_at = null
    where id = existing.id
    returning * into result;
  else
    insert into public.registrations (event_id, user_id, ticket_type_id, status, answers, amount, currency, payment_status)
    values (ev.id, uid, tt.id, new_status, coalesce(p_answers, '{}'::jsonb), tt.price, tt.currency,
            case when tt.price > 0 then 'pending' else 'none' end)
    returning * into result;
  end if;

  return result;
end;
$$;

-- ─── Waitlist ───────────────────────────────────────────────────────────────
-- Moves people off the waitlist (oldest first) while there is room. Returns who moved.
create or replace function public.promote_waitlist(p_event_id uuid)
returns setof public.registrations
language plpgsql security definer set search_path = '' as $$
declare
  ev public.events;
  w public.registrations;
  price numeric;
begin
  select * into ev from public.events where id = p_event_id for update;
  if ev.id is null or ev.status <> 'published' then
    return;
  end if;
  for w in
    select * from public.registrations
    where event_id = p_event_id and status = 'waitlisted'
    order by created_at
  loop
    exit when not public.has_room(p_event_id, w.ticket_type_id, w.user_id);
    select tt.price into price from public.ticket_types tt where tt.id = w.ticket_type_id;
    update public.registrations set
      status = case
        when ev.requires_approval then 'pending'
        when coalesce(price, 0) > 0 then 'awaiting_payment'
        else 'going' end
    where id = w.id
    returning * into w;
    return next w;
  end loop;
end;
$$;

-- ─── Cancel (by the attendee) ───────────────────────────────────────────────
create or replace function public.cancel_registration(p_event_id uuid)
returns public.registrations
language plpgsql security definer set search_path = '' as $$
declare
  result public.registrations;
begin
  update public.registrations set status = 'cancelled', checked_in_at = null
  where event_id = p_event_id and user_id = auth.uid() and status <> 'cancelled'
  returning * into result;
  if result.id is null then
    raise exception 'You are not registered for this event';
  end if;
  perform public.promote_waitlist(p_event_id);
  return result;
end;
$$;

-- ─── Approve / decline (by the organiser) ───────────────────────────────────
create or replace function public.decide_registration(p_registration_id uuid, p_decision text)
returns public.registrations
language plpgsql security definer set search_path = '' as $$
declare
  reg public.registrations;
  price numeric;
  result public.registrations;
begin
  select * into reg from public.registrations where id = p_registration_id;
  if reg.id is null or not public.can_manage_event(reg.event_id) then
    raise exception 'Registration not found';
  end if;
  if p_decision not in ('approve', 'decline') then
    raise exception 'Decision must be approve or decline';
  end if;

  if p_decision = 'decline' then
    update public.registrations set status = 'declined', decided_at = now()
    where id = reg.id returning * into result;
    perform public.promote_waitlist(reg.event_id);
    return result;
  end if;

  if reg.status not in ('pending', 'waitlisted', 'declined') then
    return reg;  -- already approved
  end if;
  -- Approving from the waitlist/declined needs a free spot; a pending person already holds one.
  if reg.status <> 'pending' and not public.has_room(reg.event_id, reg.ticket_type_id, reg.user_id) then
    raise exception 'The event is full. Increase the capacity to approve more people.';
  end if;
  select tt.price into price from public.ticket_types tt where tt.id = reg.ticket_type_id;
  update public.registrations set
    status = case when coalesce(price, 0) > 0 and reg.payment_status <> 'paid' then 'awaiting_payment' else 'going' end,
    decided_at = now()
  where id = reg.id returning * into result;
  return result;
end;
$$;

-- ─── Check-in at the door (organiser scans the QR code) ─────────────────────
create or replace function public.check_in(p_event_id uuid, p_code text)
returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  reg public.registrations;
  guest_name text;
  ticket_name text;
begin
  if not public.can_manage_event(p_event_id) then
    raise exception 'You can''t check guests in for this event';
  end if;

  select * into reg from public.registrations
  where event_id = p_event_id and qr_code = lower(trim(p_code));
  if reg.id is null then
    return jsonb_build_object('result', 'not_found');
  end if;

  select coalesce(full_name, email) into guest_name from public.profiles where id = reg.user_id;
  select name into ticket_name from public.ticket_types where id = reg.ticket_type_id;

  if reg.status <> 'going' then
    return jsonb_build_object('result', 'not_going', 'status', reg.status, 'name', guest_name, 'ticket', ticket_name);
  end if;
  if reg.checked_in_at is not null then
    return jsonb_build_object('result', 'already', 'name', guest_name, 'ticket', ticket_name,
                              'checked_in_at', reg.checked_in_at, 'registration_id', reg.id);
  end if;

  update public.registrations set checked_in_at = now(), checked_in_by = auth.uid() where id = reg.id;
  return jsonb_build_object('result', 'checked_in', 'name', guest_name, 'ticket', ticket_name, 'registration_id', reg.id);
end;
$$;

create or replace function public.undo_check_in(p_registration_id uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare
  ev uuid;
begin
  select event_id into ev from public.registrations where id = p_registration_id;
  if ev is null or not public.can_manage_event(ev) then
    raise exception 'Registration not found';
  end if;
  update public.registrations set checked_in_at = null, checked_in_by = null where id = p_registration_id;
end;
$$;

-- ─── Payments hand-off (server only — called by the payment webhook) ────────
create or replace function public.mark_registration_paid(
  p_registration_id uuid, p_checkout_session_id text, p_payment_intent_id text
)
returns public.registrations
language plpgsql security definer set search_path = '' as $$
declare
  result public.registrations;
begin
  update public.registrations set
    status = 'going', payment_status = 'paid',
    stripe_checkout_session_id = p_checkout_session_id,
    stripe_payment_intent_id = p_payment_intent_id
  where id = p_registration_id and status in ('awaiting_payment', 'cancelled', 'waitlisted')
  returning * into result;
  return result;
end;
$$;

-- Event page: per-ticket-type availability ("Sold out", "3 left") without exposing who registered.
-- Uses the same rules as register_for_event (taken_spots / has_room), so the page shows
-- "Join waitlist" exactly when registering would put the viewer on the waitlist.

create or replace function public.ticket_availability(p_event_id uuid)
returns table (ticket_type_id uuid, remaining int, event_remaining int)
language sql stable security definer set search_path = '' as $$
  with ev as (
    select e.id, e.capacity,
      case when e.capacity is null then null
           else greatest(0, e.capacity - public.taken_spots(e.id, null, (select auth.uid())))
      end as left_total
    from public.events e
    where e.id = p_event_id
  )
  select
    tt.id,
    case
      when tt.quantity is null then ev.left_total
      else least(
        greatest(0, tt.quantity - public.taken_spots(ev.id, tt.id, (select auth.uid()))),
        coalesce(ev.left_total, 2147483647)
      )
    end,
    ev.left_total
  from ev
  join public.ticket_types tt on tt.event_id = ev.id
  order by tt.sort_order, tt.created_at;
$$;

-- Organiser studio: slug checks, public follower counts and team management.
-- Profiles RLS hides other users, so team lookups go through these SECURITY DEFINER functions.
-- Re-runnable: everything is `create or replace` and grants are idempotent.

-- ─── Slug availability (pending/rejected organisers are hidden by RLS) ─────────
create or replace function public.organiser_slug_available(p_slug text)
returns boolean language sql stable security definer set search_path = '' as $$
  select not exists (
    select 1 from public.organisers where slug = lower(trim(p_slug))
  );
$$;

-- ─── Public follower count (follows RLS only shows your own rows) ──────────────
create or replace function public.organiser_follower_count(org uuid)
returns int language sql stable security definer set search_path = '' as $$
  select count(*)::int
  from public.follows f
  join public.organisers o on o.id = f.organiser_id
  where f.organiser_id = org
    and (o.status = 'approved' or public.is_org_member(org) or public.is_admin());
$$;

-- ─── Team: list members with their name + email ───────────────────────────────
create or replace function public.organiser_members_list(org uuid)
returns table (
  user_id    uuid,
  full_name  text,
  email      text,
  avatar_url text,
  role       text,
  created_at timestamptz
)
language plpgsql stable security definer set search_path = '' as $$
begin
  if not (public.is_org_member(org) or public.is_admin()) then
    raise exception 'Only members of this organiser can see its team';
  end if;
  return query
    select m.user_id, p.full_name, p.email, p.avatar_url, m.role, m.created_at
    from public.organiser_members m
    left join public.profiles p on p.id = m.user_id
    where m.organiser_id = org
    order by (m.role = 'owner') desc, m.created_at;
end;
$$;

-- ─── Team: owner adds someone by email (or changes their role) ────────────────
create or replace function public.add_organiser_member(org uuid, member_email text, member_role text default 'editor')
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  target uuid;
begin
  if not (public.is_org_owner(org) or public.is_admin()) then
    raise exception 'Only owners can add team members';
  end if;
  if member_role not in ('owner', 'editor') then
    raise exception 'Role must be owner or editor';
  end if;

  select id into target from public.profiles where lower(email) = lower(trim(member_email)) limit 1;
  if target is null then
    raise exception 'No ORBIT account uses %. Ask them to sign in to ORBIT once, then add them again.', trim(member_email);
  end if;

  insert into public.organiser_members (organiser_id, user_id, role)
  values (org, target, member_role)
  on conflict (organiser_id, user_id) do update set role = excluded.role;
  return target;
end;
$$;

-- ─── Team: owner removes a member (never the last owner) ──────────────────────
create or replace function public.remove_organiser_member(org uuid, member uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare
  member_role text;
begin
  if not (public.is_org_owner(org) or public.is_admin()) then
    raise exception 'Only owners can remove team members';
  end if;

  select role into member_role from public.organiser_members where organiser_id = org and user_id = member;
  if member_role is null then
    raise exception 'That person is not on this team';
  end if;
  if member_role = 'owner' and (
    select count(*) from public.organiser_members where organiser_id = org and role = 'owner'
  ) <= 1 then
    raise exception 'Every organiser needs at least one owner';
  end if;

  delete from public.organiser_members where organiser_id = org and user_id = member;
end;
$$;

-- ─── Checkout hold ──────────────────────────────────────────────────────────
-- register_for_event holds a paid spot for 30 minutes (see taken_spots). Before opening a new
-- Stripe checkout we ask: is the hold still live, or — if it lapsed — is there still room?
create or replace function public.payment_hold_ok(p_registration_id uuid)
returns boolean
language plpgsql stable security definer set search_path = '' as $$
declare
  reg public.registrations;
begin
  select * into reg from public.registrations where id = p_registration_id;
  if reg.id is null or reg.status <> 'awaiting_payment' then
    return false;
  end if;
  if reg.updated_at > now() - interval '30 minutes' then
    return true;
  end if;
  return public.has_room(reg.event_id, reg.ticket_type_id, reg.user_id);
end;
$$;

create or replace function public.log_admin_action(
  p_action text,
  p_target_type text,
  p_target_id text default null,
  p_details jsonb default '{}'::jsonb
)
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  new_id uuid;
begin
  if not public.is_admin() then
    raise exception 'Only admins can write to the audit log';
  end if;
  insert into public.admin_audit_log (actor, action, target_type, target_id, details)
  values (auth.uid(), p_action, p_target_type, p_target_id, coalesce(p_details, '{}'::jsonb))
  returning id into new_id;
  return new_id;
end;
$$;

-- Sign-ups per UK calendar day for the last p_days days (zero-filled, oldest first).
create or replace function public.admin_signups_daily(p_days int default 30)
returns table (day date, signups int)
language plpgsql stable security definer set search_path = '' as $$
declare
  today date := (now() at time zone 'Europe/London')::date;
  span int := least(greatest(coalesce(p_days, 30), 1), 365);
begin
  if not public.is_admin() then
    raise exception 'Admins only';
  end if;
  return query
    select g.d::date, coalesce(c.total, 0)::int
    from generate_series((today - (span - 1))::timestamp, today::timestamp, interval '1 day') as g(d)
    left join (
      select (p.created_at at time zone 'Europe/London')::date as uk_day, count(*) as total
      from public.profiles p
      where p.created_at >= ((today - (span - 1))::timestamp at time zone 'Europe/London')
      group by 1
    ) c on c.uk_day = g.d::date
    order by 1;
end;
$$;

-- A push endpoint belongs to one browser. If someone else signs in on the same browser and turns
-- push on, the subscription moves to them (holding the endpoint + keys proves it's their device).
create or replace function public.save_push_subscription(
  p_endpoint text, p_p256dh text, p_auth text, p_user_agent text default null
)
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  uid uuid := auth.uid();
  result uuid;
begin
  if uid is null then
    raise exception 'Sign in to turn on notifications';
  end if;
  insert into public.push_subscriptions (user_id, endpoint, p256dh, auth, user_agent)
  values (uid, p_endpoint, p_p256dh, p_auth, left(p_user_agent, 300))
  on conflict (endpoint) do update set
    user_id = excluded.user_id,
    p256dh = excluded.p256dh,
    auth = excluded.auth,
    user_agent = excluded.user_agent
  returning id into result;
  return result;
end;
$$;

create trigger notification_preferences_updated_at before update on public.notification_preferences
  for each row execute function public.set_updated_at();

create trigger event_sources_updated_at before update on public.event_sources
  for each row execute function public.set_updated_at();

-- Owner/admin creates an invite link for an APPROVED organisation. Returns the code.
create or replace function public.create_organiser_invite(org uuid)
returns text language plpgsql security definer set search_path = '' as $$
declare
  status_now text;
  new_code   text;
begin
  if (select auth.uid()) is null then
    raise exception 'Sign in to create an invite';
  end if;
  if not (public.is_org_owner(org) or public.is_admin()) then
    raise exception 'Only owners can create team invites';
  end if;
  select status into status_now from public.organisers where id = org;
  if status_now is null then
    raise exception 'Organiser not found';
  end if;
  if status_now <> 'approved' then
    raise exception 'Team invites unlock once your organisation is approved';
  end if;

  insert into public.organiser_invites (organiser_id, created_by)
  values (org, (select auth.uid()))
  returning code into new_code;
  return new_code;
end;
$$;

-- What the /join page needs to render, for a signed-in person holding a code.
-- Returns no row for unknown codes. The page works out the human message from these fields.
create or replace function public.peek_organiser_invite(p_code text)
returns table (
  organiser_id   uuid,
  organiser_name text,
  organiser_slug text,
  logo_url       text,
  org_status     text,
  role           text,
  expires_at     timestamptz,
  max_uses       int,
  uses           int,
  revoked        boolean,
  already_member boolean
)
language sql stable security definer set search_path = '' as $$
  select o.id, o.name, o.slug, o.logo_url, o.status, i.role, i.expires_at, i.max_uses, i.uses, i.revoked,
         exists (select 1 from public.organiser_members m where m.organiser_id = o.id and m.user_id = (select auth.uid()))
  from public.organiser_invites i
  join public.organisers o on o.id = i.organiser_id
  where i.code = trim(p_code)
    and (select auth.uid()) is not null;
$$;

-- Signed-in person accepts an invite and becomes a team member. Returns the organiser.
create or replace function public.accept_organiser_invite(p_code text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  inv      public.organiser_invites;
  org      public.organisers;
  inserted int;
begin
  if (select auth.uid()) is null then
    raise exception 'Sign in to join a team';
  end if;

  select * into inv from public.organiser_invites where code = trim(p_code) for update;
  if inv.id is null then
    raise exception 'This invite link is not valid';
  end if;
  if inv.revoked then
    raise exception 'This invite link has been turned off';
  end if;
  if inv.expires_at <= now() then
    raise exception 'This invite link has expired';
  end if;
  if inv.uses >= inv.max_uses then
    raise exception 'This invite link has reached its limit';
  end if;

  select * into org from public.organisers where id = inv.organiser_id;
  if org.status <> 'approved' then
    raise exception 'This organisation is not accepting team members right now';
  end if;

  insert into public.organiser_members (organiser_id, user_id, role)
  values (inv.organiser_id, (select auth.uid()), inv.role)
  on conflict (organiser_id, user_id) do nothing;
  get diagnostics inserted = row_count;

  if inserted > 0 then
    update public.organiser_invites set uses = uses + 1 where id = inv.id;
  end if;

  return jsonb_build_object('id', org.id, 'slug', org.slug, 'name', org.name, 'joined', inserted > 0);
end;
$$;

