-- Upcoming events on the admin overview count each event once: a recurring series is one event
-- however many dates it has, and a duplicate copy from a second source isn't counted. The number
-- of dates is reported separately (upcoming_dates, dates_this_week).
create or replace function public.admin_stats()
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare
  result jsonb;
begin
  if not public.is_admin() then
    raise exception 'Admins only';
  end if;

  select jsonb_build_object(
    'users',              (select count(*) from public.profiles),
    'onboarded',          (select count(*) from public.profiles where onboarded_at is not null),
    'verified_students',  (select count(*) from public.profiles where is_verified_student),
    'signups_7d',         (select count(*) from public.profiles where created_at >= now() - interval '7 days'),
    'organisers_pending', (select count(*) from public.organisers where status = 'pending'),
    'organisers_approved',(select count(*) from public.organisers where status = 'approved'),
    'upcoming_events',    (select count(distinct coalesce(series_key, id::text)) from public.events
                            where status = 'published' and duplicate_of is null
                              and coalesce(ends_at, starts_at) >= now()),
    'upcoming_dates',     (select count(*) from public.events
                            where status = 'published' and duplicate_of is null
                              and coalesce(ends_at, starts_at) >= now()),
    'events_this_week',   (select count(distinct coalesce(series_key, id::text)) from public.events
                            where status = 'published' and duplicate_of is null and starts_at >= now()
                              and starts_at < now() + interval '7 days'),
    'dates_this_week',    (select count(*) from public.events
                            where status = 'published' and duplicate_of is null and starts_at >= now()
                              and starts_at < now() + interval '7 days'),
    'needs_review',       (select count(*) from public.events
                            where needs_review and status not in ('removed', 'expired')),
    'registrations',      (select count(*) from public.registrations
                            where status not in ('cancelled', 'declined')),
    'registrations_7d',   (select count(*) from public.registrations
                            where status not in ('cancelled', 'declined')
                              and created_at >= now() - interval '7 days'),
    'check_ins',          (select count(*) from public.registrations where checked_in_at is not null)
  ) into result;
  return result;
end;
$$;

-- Explore's category tabs and Interest filter show how many upcoming events each has. Counted
-- here so the page gets a few numbers instead of every event row: a recurring series counts once
-- however many dates it has, and duplicate copies aren't counted. RLS applies (security invoker).
--
-- p_interests maps each interest to the tags that count as it ({"technology": ["technology", "tech"]}),
-- so an event tagged with two synonyms of one interest still counts once.
create or replace function public.discovery_counts(p_interests jsonb default '{}'::jsonb)
returns table (kind text, key text, events bigint)
language sql stable security invoker set search_path = '' as $$
  with upcoming as (
    select coalesce(e.series_key, e.id::text) as event_key, e.category_id, e.tags
    from public.events e
    where e.status = 'published' and e.duplicate_of is null and coalesce(e.ends_at, e.starts_at) >= now()
  )
  select 'all', null, count(distinct u.event_key) from upcoming u
  union all
  select 'category', u.category_id::text, count(distinct u.event_key)
  from upcoming u where u.category_id is not null group by u.category_id
  union all
  select 'interest', i.key, count(distinct u.event_key)
  from jsonb_each(coalesce(p_interests, '{}'::jsonb)) i
  join upcoming u on u.tags && array(select jsonb_array_elements_text(i.value))
  group by i.key;
$$;
